interface.signature:
interface Task {
  id: string;
  title: string;
  description?: string;
  completed: boolean;
  createdAt: number;
  completedAt?: number;
  deferredUntil?: number;
  metadata: TaskMetadata;
}

export const selectVisibleTasks = createSelector(
  [selectAllTasks],
  (tasks) => tasks.filter(task => 
    !task.deferredUntil || task.deferredUntil <= Date.now()
  )
);
